class Solution {
public:
    std::string categorizeBox(int length, int width, int height, int mass) {
        long long vol = (long long)length * width * height;
        bool is_bulky = (length >= 10000 || width >= 10000 || height >= 10000 || vol >= 1000000000LL);
        bool is_heavy = (mass >= 100);
        if (is_bulky && is_heavy) return "Both";
        if (is_bulky) return "Bulky";
        if (is_heavy) return "Heavy";
        return "Neither";
    }
};

class Solution {
    public String categorizeBox(int length, int width, int height, int mass) {
